class MyCalendar:
    def __init__(self):
        self.bookings = []

    def book(self, start, end):
        for s, e in self.bookings:
            if start < e and s < end:
                return False
        self.bookings.append((start, end))
        return True


def my_calendar(operations, args):
    calendar = MyCalendar()
    results = []
    for op, arg in zip(operations, args):
        if op == 'book':
            results.append(calendar.book(arg[0], arg[1]))
    return results
